function report(n) {
  const list = Array.from({ length: n }, (_, i) => i)
  let pairs = 0
  for (let i = 0; i < list.length; i++) {
    for (let j = i + 1; j < list.length; j++) pairs += 1
  }
  let steps = 0
  const seen = new Set()
  for (const item of list) {
    steps += 1
    seen.add(item)
  }
  return `loops:${pairs} set:${steps}`
}
console.log(report(5))
module.exports = { report }
